package com.bossmode.entity.sovereign;

import com.geckolib.animation.RawAnimation;

/**
 * GeckoLib controllers and clips of the Void Sovereign
 * ({@code assets/boss_mode/geckolib/animations/entity/void_sovereign.animation.json}, generated by tools/blender).
 */
public final class SovereignAnimations {
	public static final String BASE_CONTROLLER = "base";
	public static final String ACTION_CONTROLLER = "action";
	public static final String HURT_CONTROLLER = "hurt";

	/** Trigger names double as clip names. */
	public static final String[] ACTION_CLIPS = {"claw_swipe", "tentacle_lash", "ground_pound", "void_orbs", "rift_eruption", "void_grasp",
			"black_hole", "void_step", "eclipse", "soul_drain", "summon", "shield", "roar", "skyward_lash", "gravity_well", "abyssal_carapace",
			"soul_chains", "null_sweep", "tentacle_field", "dimension_rend", "abyssal_spears", "oblivion"};

	public static final String TRIGGER_ROAR = "roar";
	public static final String TRIGGER_HURT = "hurt";

	public static final RawAnimation IDLE = RawAnimation.begin().thenLoop(clip("idle"));
	public static final RawAnimation WALK = RawAnimation.begin().thenLoop(clip("walk"));
	public static final RawAnimation SPAWN = RawAnimation.begin().thenPlayAndHold(clip("spawn"));
	public static final RawAnimation DEATH = RawAnimation.begin().thenPlayAndHold(clip("death"));
	public static final RawAnimation HURT = RawAnimation.begin().thenPlay(clip("hurt"));

	private SovereignAnimations() {
	}

	public static String clip(String name) {
		return "animation.void_sovereign." + name;
	}

	public static RawAnimation once(String name) {
		return RawAnimation.begin().thenPlay(clip(name));
	}
}
